import{_ as e,o as a,c as s,a3 as r}from"./chunks/framework.Cj_fzHAr.js";const n="/manual/img/documentos/gestion.png",t="/manual/img/documentos/repositorio.png",h=JSON.parse('{"title":"Documentos","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/documentos.md","filePath":"modulos/documentos.md"}'),i={name:"modulos/documentos.md"};function l(u,o,c,d,m,p){return a(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="documentos" tabindex="-1">Documentos <a class="header-anchor" href="#documentos" aria-label="Permalink to &quot;Documentos&quot;">​</a></h1><p>El módulo de <strong>Documentos</strong> es donde vive toda la documentación de seguridad de tu empresa y tus obras: políticas, reglamentos, matrices de riesgo, certificados, procedimientos, entregas de EPP y más. Reemplaza las carpetas de papel por un repositorio digital único, ordenado y siempre disponible.</p><p>Aquí harás tres cosas principales: <strong>cargar</strong> documentos, <strong>asignarlos</strong> a las personas que deben conocerlos o firmarlos, y <strong>consultarlos o descargarlos</strong> cuando los necesites.</p><blockquote><p>💡 Muchos documentos obligatorios del DS 44 ya se crean solos cuando creas una obra. En este módulo terminas de completarlos subiendo el archivo y asignándolos a las personas.</p></blockquote><h2 id="las-dos-vistas-de-documentos" tabindex="-1">Las dos vistas de documentos <a class="header-anchor" href="#las-dos-vistas-de-documentos" aria-label="Permalink to &quot;Las dos vistas de documentos&quot;">​</a></h2><p>La plataforma organiza los documentos en dos pantallas complementarias:</p><ul><li><strong>Gestión documental</strong> — para <strong>crear, asignar y firmar</strong> documentos. Es la vista de trabajo, usada principalmente por roles de gestión (Administrador, Prevencionista, Jefe de Obra).</li><li><strong>Repositorio de documentos</strong> — para <strong>buscar, consultar y descargar</strong> documentos ya existentes. Pensada para encontrar rápido cualquier archivo.</li></ul><p>Accedes a ellas desde el menú lateral, en la sección de <strong>Documentos</strong>.</p><h2 id="gestion-documental" tabindex="-1">Gestión documental <a class="header-anchor" href="#gestion-documental" aria-label="Permalink to &quot;Gestión documental&quot;">​</a></h2><p>Al abrir <strong>Gestión documental</strong> verás, en la parte superior, unas tarjetas con el resumen: <strong>Total Documentos</strong>, <strong>Con Firmas</strong>, <strong>Pendientes</strong> y <strong>Asignaciones</strong>. Debajo, la lista de documentos con las columnas <strong>Documento</strong>, <strong>Asignaciones</strong>, <strong>Fecha</strong> y <strong>Acciones</strong>.</p><p><img src="'+n+'" alt="Pantalla de Gestión documental con las tarjetas de resumen y la tabla de documentos"></p><h3 id="subir-un-documento-nuevo" tabindex="-1">Subir un documento nuevo <a class="header-anchor" href="#subir-un-documento-nuevo" aria-label="Permalink to &quot;Subir un documento nuevo&quot;">​</a></h3><ol><li>Haz clic en el botón <strong>Nuevo Documento</strong> (arriba a la derecha).</li><li>Se abrirá la ventana <strong>Nuevo Documento</strong>. Completa: <ul><li><strong>Tipo de Documento</strong> <em>(obligatorio)</em> — elige de la lista qué tipo es (política, reglamento, certificado, etc.).</li><li><strong>Título</strong> <em>(obligatorio)</em> — un nombre claro para identificarlo (ej.: <em>&quot;IRL - Soldador&quot;</em>).</li><li><strong>Descripción</strong> <em>(opcional)</em> — una nota sobre el contenido.</li><li><strong>Archivo del Documento</strong> — selecciona el archivo desde tu computador.</li></ul></li><li>Haz clic en <strong>Crear Documento</strong>. Mientras se procesa verás <em>&quot;Subiendo…&quot;</em> y luego <em>&quot;Creando…&quot;</em>.</li></ol><blockquote><p>📎 Sube los archivos preferentemente en <strong>PDF</strong>. Así se ven igual en cualquier dispositivo y se conservan correctamente para una eventual fiscalización.</p></blockquote><h3 id="buscar-un-documento" tabindex="-1">Buscar un documento <a class="header-anchor" href="#buscar-un-documento" aria-label="Permalink to &quot;Buscar un documento&quot;">​</a></h3><p>Usa el campo <strong>&quot;Buscar documentos…&quot;</strong> para filtrar la lista por nombre. Es la forma más rápida de encontrar algo cuando hay muchos documentos.</p><h3 id="ver-el-detalle-asignar-y-firmar" tabindex="-1">Ver el detalle, asignar y firmar <a class="header-anchor" href="#ver-el-detalle-asignar-y-firmar" aria-label="Permalink to &quot;Ver el detalle, asignar y firmar&quot;">​</a></h3><p>Al hacer clic en un documento se abre su <strong>ficha</strong>, donde puedes:</p><ul><li><strong>Ver una vista previa</strong> del archivo sin descargarlo.</li><li><strong>Descargar</strong> el archivo.</li><li><strong>Asignar</strong> el documento a una o varias personas para que lo firmen o lo conozcan.</li><li><strong>Firmar</strong> el documento (si te corresponde a ti).</li></ul><p>En la columna <strong>Asignaciones</strong> de la lista verás cuántas personas ya firmaron y cuántas están pendientes (por ejemplo, <em>&quot;3/5 firmados · 2 pendientes&quot;</em>).</p><blockquote><p>✅ La etiqueta <strong>Empresa</strong> junto a un documento indica que es un documento corporativo (válido para toda la empresa), no de una obra puntual.</p></blockquote><h2 id="repositorio-de-documentos" tabindex="-1">Repositorio de documentos <a class="header-anchor" href="#repositorio-de-documentos" aria-label="Permalink to &quot;Repositorio de documentos&quot;">​</a></h2><p>El <strong>Repositorio</strong> es la vista de consulta. Arriba encontrarás pestañas para filtrar por ámbito:</p><ul><li><strong>General</strong> — documentos de la empresa y las obras.</li><li><strong>Personal</strong> — documentos asociados a una persona en particular.</li><li><strong>Mis documentos</strong> — tus propios documentos (los que te corresponden a ti).</li></ul><p><img src="'+t+'" alt="Repositorio de documentos con las pestañas General, Personal y Mis documentos"></p><p>Para encontrar algo, usa el buscador <strong>&quot;Buscar en todo el repositorio…&quot;</strong>. Sobre cada documento tienes botones para <strong>previsualizar</strong> (ver sin descargar) y <strong>descargar</strong>.</p><p>Si un documento aún no tiene archivo cargado, verás la nota <em>&quot;Sin archivo&quot;</em>: significa que está creado pero todavía falta subir el PDF.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Cuál es la diferencia entre &quot;Gestión documental&quot; y &quot;Repositorio&quot;?</strong><strong>Gestión documental</strong> es para <em>trabajar</em> los documentos (crearlos, asignarlos, firmarlos). El <strong>Repositorio</strong> es para <em>consultarlos y descargarlos</em>. Si solo necesitas encontrar un archivo, usa el Repositorio; si necesitas crear o asignar, usa Gestión documental.</p><p><strong>Creé el documento pero aparece &quot;Sin archivo&quot;.</strong> Es porque se creó el registro del documento sin subir el archivo. Ábrelo y carga el PDF correspondiente para completarlo.</p><p><strong>Asigné un documento pero la persona no lo ha firmado.</strong> La asignación genera la solicitud, pero la firma la realiza cada persona. Aparecerá como pendiente hasta que firme. La persona verá el documento en su Dashboard y en su Bandeja de Entrada como una tarea pendiente. Revisa el módulo de <a href="/manual/modulos/firmas.html">Firmas Digitales</a>.</p><p><strong>¿Quién puede crear documentos?</strong> Principalmente los roles de gestión (Administrador, Prevencionista, Jefe de Obra). Un Trabajador normalmente solo ve y firma los documentos que le asignan. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p><p><strong>No encuentro un documento que sé que existe.</strong> Revisa que estés en la pestaña correcta del Repositorio (General / Personal / Mis documentos) y usa el buscador. Algunos documentos personales solo aparecen en la pestaña &quot;Personal&quot; o &quot;Mis documentos&quot;.</p><p><strong>¿Puedo ver un documento sin descargarlo?</strong> Sí. Usa el botón de <strong>previsualizar</strong>: abre una vista del archivo dentro de la misma plataforma, sin necesidad de guardarlo en tu equipo.</p>',34)])])}const b=e(i,[["render",l]]);export{h as __pageData,b as default};
